++/* IMPORTANT: caller must free and zero the returned string
++ *
++ * NOTE: this function is intentionally written to be
++ * specific to the snapd recovery key format.
++ */
++gchar *
++fu_console_input_secret_snapd_recovery_key(FuConsole *self,
++					   guint key_len,
++					   GError **error,
++					   const gchar *format,
++					   ...)
++{
++	struct termios oldt;
++	struct termios newt;
++
++	gchar buffer[256] = {0};
++	gsize input_len = 0;
++	gsize group_len = 5;
++	int ch;
++
++	gchar *out = NULL;
++	va_list args;
++	g_autofree gchar *tmp = NULL;
++
++	int cancelled = FALSE;
++
++	va_start(args, format);
++	tmp = g_strdup_vprintf(format, args);
++	va_end(args);
++
++	if (key_len + (key_len / group_len - 1) >= sizeof(buffer)) {
++		g_set_error_literal(error,
++				    FWUPD_ERROR,
++				    FWUPD_ERROR_INTERNAL,
++				    "key_len is too large for internal buffer");
++		return NULL;
++	}
++
++	do {
++		fu_console_print_full(self, FU_CONSOLE_PRINT_FLAG_NONE, "%s: ", tmp);
++
++		if (tcgetattr(STDIN_FILENO, &oldt) == -1) {
++			g_set_error_literal(error,
++					    FWUPD_ERROR,
++					    FWUPD_ERROR_INTERNAL,
++					    "Failed to get terminal attributes");
++			return NULL;
++		}
++
++		newt = oldt;
++		newt.c_lflag &= ~(ECHO | ICANON);
++
++		if (tcsetattr(STDIN_FILENO, TCSANOW, &newt) == -1) {
++			g_set_error_literal(error,
++					    FWUPD_ERROR,
++					    FWUPD_ERROR_INTERNAL,
++					    "Failed to set terminal attributes");
++			return NULL;
++		}
++
++		do {
++			ch = getchar();
++
++			if ((ch == '\n' || ch == '\r'))
++				break;
++
++			/* Ctrl-D, Ctrl-C or EOF */
++			if (ch == EOF || ch == 0x03 || ch == 0x04) {
++				cancelled = TRUE;
++				break;
++			}
++
++			/* handle backspace (ASCII BS or DEL) */
++			if ((ch == 0x08 || ch == 0x7f) && input_len > 0) {
++				input_len--;
++
++				/* erase '*' */
++				g_print("\b \b");
++
++				/* erase hyphen if we crossed a boundary */
++				if (input_len % group_len == 0 && input_len > 0) {
++					g_print("\b \b");
++				}
++				continue;
++			}
++
++			/* accept hyphenated input if pasted */
++			if (ch == '-')
++				continue;
++			if (!isdigit((unsigned char)ch))
++				continue;
++			if (input_len >= key_len)
++				continue;
++
++			buffer[input_len++] = (gchar)ch;
++			g_print("*");
++
++			/* print hyphen after every group except last */
++			if (input_len % group_len == 0 && input_len < key_len) {
++				g_print("-");
++			}
++		} while (TRUE);
++
++		/* restore terminal for this attempt */
++		if (tcsetattr(STDIN_FILENO, TCSANOW, &oldt) == -1) {
++			g_warning("Failed to restore terminal attributes");
++		}
++		g_print("\n");
++
++		if (cancelled) {
++			/* newline for input response */
++			g_print("\n");
++			break;
++		}
++
++		if (input_len == key_len)
++			break;
++
++		explicit_bzero(buffer, sizeof(buffer));
++		input_len = 0;
++
++		fu_console_print_full(
++		    self,
++		    FU_CONSOLE_PRINT_FLAG_NONE,
++		    /* TRANSLATORS: the user has input too few digits */
++		    _("Recovery key must be exactly %u digits. Please try again."),
++		    key_len);
++		g_print("\n");
++
++	} while (TRUE);
++
++	if (!cancelled && input_len == key_len)
++		out = g_strdup(buffer);
++
++	explicit_bzero(buffer, sizeof(buffer));
++	return out;
++}
