++
++/* temporary reuse of curl from snapd-uefi-plugin.c */
++static CURLcode
++fu_util_snapd_check_recovery_key_req(const gchar *data, GError **error)
++{
++	CURLcode res = -1;
++	glong status_code = 0;
++	g_autoptr(CURL) curl = curl_easy_init();
++	struct curl_slist *hdrs = NULL;
++	const gchar *endpoint_str = "http://localhost/v2/system-volumes";
++	const gchar *action_field = "\"action\":\"check-recovery-key\"";
++	g_autofree gchar *key_field = g_strdup_printf("\"recovery-key\":\"%s\"", data);
++	g_autofree gchar *msg = NULL;
++	const gchar *snapd_socket_path = "/var/run/snapd.socket";
++	g_autoptr(GByteArray) rsp_buf = g_byte_array_new();
++
++	/* set up curl */
++	(void)curl_easy_setopt(curl, CURLOPT_UNIX_SOCKET_PATH, snapd_socket_path);
++	hdrs = curl_slist_append(hdrs, "Content-Type: application/json");
++	(void)curl_easy_setopt(curl, CURLOPT_HTTPHEADER, hdrs);
++
++	msg = g_strdup_printf("{%s,%s}", action_field, key_field);
++
++	(void)curl_easy_setopt(curl, CURLOPT_URL, endpoint_str);
++
++	(void)curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, strlen(msg));
++	(void)curl_easy_setopt(curl, CURLOPT_POSTFIELDS, msg);
++
++	/* collect response for debugging */
++	(void)curl_easy_setopt(curl, CURLOPT_WRITEDATA, rsp_buf);
++	(void)curl_easy_setopt(curl,
++			       CURLOPT_WRITEFUNCTION,
++			       fu_util_snapd_check_recovery_key_rsp_cb);
++
++	res = curl_easy_perform(curl);
++	if (res != CURLE_OK) {
++		g_set_error(error,
++			    FWUPD_ERROR,
++			    FWUPD_ERROR_INTERNAL,
++			    "failed to communicate with snapd: %s",
++			    curl_easy_strerror(res));
++	}
++
++	curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &status_code);
++
++	curl_slist_free_all(hdrs);
++
++	return status_code;
++}
++
++static gboolean
++fu_util_prompt_confirm_snapd_recovery_readiness(FuConsole *console,
++						FwupdDevice *dev,
++						GError **error)
++{
++	GError *local_error = NULL;
++	g_autofree char *recovery_key = NULL;
++	CURLcode status_code;
++	const guint recovery_key_len = 40;
++
++	if (snapd_recovery_readiness_confirmed)
++		return TRUE;
++
++	do {
++		g_clear_error(&local_error);
++		recovery_key = fu_console_input_secret_snapd_recovery_key(
++		    console,
++		    recovery_key_len,
++		    &local_error,
++		    "%s",
++		    /* TRANSLATORS: prompt for the 'recovery key' - a code not a physical metal
++		     * thing */
++		    _("Please enter your volume recovery key"));
++
++		if (local_error != NULL) {
++			if (recovery_key != NULL)
++				explicit_bzero(recovery_key, strlen(recovery_key));
++			g_propagate_prefixed_error(error,
++						   local_error,
++						   "Failed to get recovery key from user: ");
++			return FALSE;
++		}
++
++		if (recovery_key == NULL || recovery_key[0] == '\0')
++			return FALSE;
++
++		g_clear_error(&local_error);
++		status_code = fu_util_snapd_check_recovery_key_req(recovery_key, &local_error);
++		explicit_bzero(recovery_key, strlen(recovery_key));
++
++		if (status_code == 400) {
++			g_clear_error(&local_error);
++			fu_console_print_full(
++			    console,
++			    FU_CONSOLE_PRINT_FLAG_WARNING | FU_CONSOLE_PRINT_FLAG_STDERR,
++			    "%s.\n",
++			    /* TRANSLATORS: the user gave an incorrect input */
++			    _("The recovery key entered is invalid, please try again"));
++			continue;
++		}
++
++		if (status_code == 401) {
++			g_clear_error(&local_error);
++			g_set_error_literal(
++			    error,
++			    FWUPD_ERROR,
++			    FWUPD_ERROR_PERMISSION_DENIED,
++			    "snapd refused to check the recovery key, permission denied. This update requires root privileges.");
++			return FALSE;
++		}
++
++		if (status_code == 200) {
++			fu_console_print_literal(console, "OK\n");
++			snapd_recovery_readiness_confirmed = TRUE;
++			return TRUE;
++		}
++
++		if (local_error != NULL) {
++			g_propagate_prefixed_error(error,
++						   local_error,
++						   "Failed to check recovery key with snapd: ");
++		} else {
++			g_set_error(error,
++				    FWUPD_ERROR,
++				    FWUPD_ERROR_INTERNAL,
++				    "Failed to check recovery key with snapd (status code %u)",
++				    status_code);
++		}
++		return FALSE;
++
++	} while (TRUE);
++}
